test("robust-plane background on a ramp recovers the released D4sigma headline", async ({ page }) => {
  await openAnalyzerTab(page);
  await uploadImage(page, "ramp_background.tif");
  // Background controls (S18e-C part B): robust plane over the four corner
  // rectangles the part-A corners action fills.
  await page.locator('select[data-k="imgBgMethod"]').selectOption("robust-plane");
  await page.locator('button[data-act="img-bg-rect-corners"]').click();
  const headline = await runAnalysis(page);
  await expect(headline).toHaveText(/^\d/, { timeout: 30_000 });
  await expect(headline).toContainText("px");
  await expect(headline).not.toContainText("suppressed");
});

test("Auto mode runs both automatic engine modes, shows provenance, and restores the defaults", async ({ page }) => {
  const width = 64;
  const height = 48;
  const cornerRects = [
    { x0: 0, y0: 0, width: 8, height: 6 },
    { x0: 56, y0: 0, width: 8, height: 6 },
    { x0: 0, y0: 42, width: 8, height: 6 },
    { x0: 56, y0: 42, width: 8, height: 6 },
  ];
  await beginCanvasTextCapture(page);
  await openAnalyzerTab(page);
  await uploadImage(page, "gauss_released.tif");

  await page.locator('button[data-act="img-auto-mode"]').click();
  await expect(page.locator('select[data-k="imgBgMethod"]')).toHaveValue("auto");
  await expect(page.locator('button[data-act="img-roi-mode"][data-arg="auto"]')).toHaveClass(/active/);
  await expect(page.locator('button[data-act="img-auto-mode"]')).toHaveClass(/active/);

  const headline = await runAnalysis(page);
  await expect(headline).toHaveText(/^\d/, { timeout: 30_000 });
  await expect(headline).toContainText("px");
  await expect(page.getByText("Auto background: robust plane over corner references.", { exact: true })).toBeVisible({ timeout: 30_000 });

  // This compact fixture already renders at full frame: the close-up selector
  // is intentionally absent when no tighter view can be derived.
  await expect
    .poll(() => canvasHasPurpleRectangleEdges(page, width, height, cornerRects), {
      message: "automatic corner references use the established purple background-rectangle overlay path",
    })
    .toBe(true);

  await page.locator('button[data-act="img-auto-mode"]').click();
  await expect(page.locator('select[data-k="imgBgMethod"]')).toHaveValue("none");
  await expect(page.locator('button[data-act="img-roi-mode"][data-arg="full"]')).toHaveClass(/active/);
  await expect(page.locator('button[data-act="img-auto-mode"]')).not.toHaveClass(/active/);
});

test("background rectangles render, edit independently from the ROI, and reset to ROI mode with method none", async ({ page }) => {
  const width = 160;
  const height = 128;
  await beginCanvasTextCapture(page);
  await openAnalyzerTab(page);
  await uploadGeneratedImage(page, "bg_draw_mode.tif", gray16Tiff(width, height));
  await page.locator('select[data-k="imgBgMethod"]').selectOption("rect-median");
  await page.locator('button[data-act="img-bg-rect-add"]').click();
  const headline = await runAnalysis(page);
  await expect(headline).toContainText("px", { timeout: 30_000 });
  await expect(page.locator('button[data-act="img-roi-mode"][data-arg="full"]')).toHaveClass(/active/);

  const imageCanvas = page.locator("#img-canvas");
  const bgDrawButton = page.getByRole("button", { name: "Background rectangle", exact: true });
  await expect(bgDrawButton).toBeVisible();
  await page.evaluate(() => {
    const capture = window as unknown as {
      modeForgeCanvasText?: string[];
      modeForgeCanvasTextPositions?: Array<{ text: string; x: number; y: number; canvasId: string }>;
      modeForgeOverlayPanels?: Array<{ x: number; y: number; width: number; height: number }>;
    };
    capture.modeForgeCanvasText = [];
    capture.modeForgeCanvasTextPositions = [];
    capture.modeForgeOverlayPanels = [];
  });
  await bgDrawButton.click();
  await expect
    .poll(() => imageCanvas.evaluate((element) => (element as HTMLCanvasElement).width), { message: "background draw mode forces the full frame" })
    .toBe(width);
  await expect
    .poll(() => imageCanvas.evaluate((element) => (element as HTMLCanvasElement).height), { message: "background draw mode keeps the full frame height" })
    .toBe(height);
  await expect(page.locator('button[data-act="img-roi-mode"][data-arg="full"]')).toHaveClass(/active/);
  await expect(page.locator('button[data-act="img-preview-view"][data-arg="closeup"]')).toBeDisabled();
  await expect(page.locator('button[data-act="img-preview-view"][data-arg="full"]')).toHaveAttribute(
    "title",
    "Full-frame view is required while drawing background rectangles.",
  );
  const initialRect = await bgRectFields(page, 0);
  await expect
    .poll(() => canvasHasPurpleRectangleEdges(page, width, height, [initialRect]), {
      message: "the default full-frame ROI and legend leave every background-rectangle edge pure purple",
    })
    .toBe(true);
  await expect.poll(() => canvasDrewText(page, "background rectangle"), { message: "background-rectangle legend entry is painted" }).toBe(true);

  // The remaining interaction coverage starts from the four standard corner
  // samples; the stricter oracle above deliberately used one occupied corner.
  await page.locator('button[data-act="img-bg-rect-corners"]').click();
  await page.locator('button[data-act="img-roi-mode"][data-arg="rect"]').click();
  const roiBefore = await roiFields(page);
  await dragFullFrameImage(page, { x: 55, y: 40 }, { x: 75, y: 55 }, width, height);
  await expect(page.locator('input[data-k="bgRectX0-4"]')).toBeVisible();
  expect(await roiFields(page)).toEqual(roiBefore);

  // Select and move the newly created rectangle, then exercise an edge and a
  // corner resize. Each commit stays on the background-rectangle list.
  const created = await bgRectFields(page, 4);
  await dragFullFrameImage(
    page,
    { x: created.x0 + created.width / 2, y: created.y0 + created.height / 2 },
    { x: created.x0 + created.width / 2 + 10, y: created.y0 + created.height / 2 + 5 },
    width,
    height,
  );
  const moved = await bgRectFields(page, 4);
  expect(moved.x0).not.toBe(created.x0);
  expect(moved.y0).not.toBe(created.y0);
  await dragFullFrameImage(page, { x: moved.x0 + moved.width, y: moved.y0 + moved.height / 2 }, { x: moved.x0 + moved.width + 10, y: moved.y0 + moved.height / 2 }, width, height);
  const edgeResized = await bgRectFields(page, 4);
  expect(edgeResized.width).toBeGreaterThan(moved.width);
  await dragFullFrameImage(
    page,
    { x: edgeResized.x0 + edgeResized.width, y: edgeResized.y0 + edgeResized.height },
    { x: edgeResized.x0 + edgeResized.width + 10, y: edgeResized.y0 + edgeResized.height + 10 },
    width,
    height,
  );
  const cornerResized = await bgRectFields(page, 4);
  expect(cornerResized.width).toBeGreaterThan(edgeResized.width);
  expect(cornerResized.height).toBeGreaterThan(edgeResized.height);

  // A new rectangle started in empty space and ending over the fifth sample
  // overlaps it. Moving their shared interior must select the later (topmost)
  // rectangle, not the earlier one.
  await dragFullFrameImage(
    page,
    { x: cornerResized.x0 - 10, y: cornerResized.y0 - 10 },
    { x: cornerResized.x0 + 10, y: cornerResized.y0 + 10 },
    width,
    height,
  );
  const fifthBeforeOverlapMove = await bgRectFields(page, 4);
  const sixthBeforeOverlapMove = await bgRectFields(page, 5);
  await dragFullFrameImage(
    page,
    { x: Math.max(fifthBeforeOverlapMove.x0, sixthBeforeOverlapMove.x0) + 5, y: Math.max(fifthBeforeOverlapMove.y0, sixthBeforeOverlapMove.y0) + 5 },
    { x: Math.max(fifthBeforeOverlapMove.x0, sixthBeforeOverlapMove.x0) + 15, y: Math.max(fifthBeforeOverlapMove.y0, sixthBeforeOverlapMove.y0) + 10 },
    width,
    height,
  );
  expect(await bgRectFields(page, 4)).toEqual(fifthBeforeOverlapMove);
  expect(await bgRectFields(page, 5)).not.toEqual(sixthBeforeOverlapMove);
  await page.locator('button[data-act="img-bg-rect-remove"][data-i="5"]').click();
  await expect(page.locator('input[data-k="bgRectX0-5"]')).toHaveCount(0);

  // ROI drag is independent: it writes only the ROI fields. Switching the
  // method to none removes the target control and keeps ROI drag as the
  // forced fallback target (R-22).
  const bgBeforeRoi = await bgRectFields(page, 4);
  await page.getByRole("button", { name: "Measurement ROI", exact: true }).click();
  await dragFullFrameImage(page, { x: 25, y: 30 }, { x: 45, y: 45 }, width, height);
  expect(await roiFields(page)).not.toEqual(roiBefore);
  expect(await bgRectFields(page, 4)).toEqual(bgBeforeRoi);

  await page.locator('select[data-k="imgBgMethod"]').selectOption("none");
  await expect(page.getByRole("button", { name: "Background rectangle", exact: true })).toHaveCount(0);
  const roiAfterMethodReset = await roiFields(page);
  await dragFullFrameImage(page, { x: 35, y: 37 }, { x: 45, y: 42 }, width, height);
  expect(await roiFields(page)).not.toEqual(roiAfterMethodReset);

  // The method-none fallback has no background-rectangle editor. Reopen the
  // rectangle-backed editor to verify that the fallback drag left its saved
  // rectangle untouched.
  await page.locator('select[data-k="imgBgMethod"]').selectOption("rect-median");
  await expect(page.locator('input[data-k="bgRectX0-4"]')).toBeVisible();
  expect(await bgRectFields(page, 4)).toEqual(bgBeforeRoi);

  const pngDownloadPromise = page.waitForEvent("download");
  await page.locator('button[data-act="img-export-png"]').click();
  const pngDownload = await pngDownloadPromise;
  expect(pngDownload.suggestedFilename()).toBe("bg_draw_mode.closeup.png");
  const pngPath = await pngDownload.path();
  if (typeof pngPath !== "string") throw new Error("PNG export did not produce a local file");
  expect(readFileSync(pngPath).subarray(0, 8).toString("hex")).toBe("89504e470d0a1a0a");
});

test("a matching dark pedestal changes exported axial symmetry from the none-method run", async ({ page }) => {
  await openAnalyzerTab(page);
  await uploadImage(page, "gauss_released.tif");
  await page.locator('select[data-k="imgBgMethod"]').selectOption("none");
  const noneHeadline = await runAnalysis(page);
  await expect(noneHeadline).toContainText("px", { timeout: 30_000 });
  const noneReport = await downloadAnalysisJson(page);
  if (noneReport.symmetry === null) throw new Error("none-method analysis did not export symmetry");

  await page.locator('select[data-k="imgBgMethod"]').selectOption("dark-frame");
  await expect(page.locator('button[data-act="img-bg-pick-dark"]')).toBeVisible();
  await uploadDarkFrame(page, "dark_pedestal.tif");
  // Decode is async; the loaded note (T.imgBgDarkLoaded) is the UI signal.
  await expect(page.getByText("dark_pedestal.tif", { exact: false })).toBeVisible({ timeout: 15_000 });
  await expect(page.getByText("Dark frame dimensions 16×12 do not match image dimensions 64×48.", { exact: true })).toHaveCount(0);
  await expect(page.getByText("The dark frame file could not be read.", { exact: true })).toHaveCount(0);
  await expect(page.getByRole("button", { name: "Run analysis", exact: true })).toBeEnabled();
  const darkHeadline = await runAnalysis(page);
  await expect(darkHeadline).toContainText("px", { timeout: 30_000 });
  const darkReport = await downloadAnalysisJson(page);
  if (darkReport.symmetry === null) throw new Error("dark-frame analysis did not export symmetry");

  expect(darkReport.symmetry.axialAsymmetryX).not.toBe(noneReport.symmetry.axialAsymmetryX);
  expect(darkReport.symmetry.axialAsymmetryY).not.toBe(noneReport.symmetry.axialAsymmetryY);
});

