test("suggested ROI applies back into the rectangle inputs", async ({ page }) => {
  await openAnalyzerTab(page);
  await uploadImage(page, "gauss_released.tif");
  await runAnalysis(page);
  // The informational suggestion line (T.imgSuggestedRoi) is rendered from
  // the result's roi.suggestion.
  await expect(page.getByText("Suggested ROI", { exact: false })).toBeVisible({ timeout: 30_000 });
  await page.locator('button[data-act="img-apply-suggestion"]').click();
  // Applying the suggestion switches ROI mode to rectangle and fills the
  // four numeric inputs (data-k names from views/image.ts).
  for (const key of ["imgRoiX0", "imgRoiY0", "imgRoiW", "imgRoiH"]) {
    await expect(page.locator(`input[data-k="${key}"]`)).toHaveValue(/\d/);
  }
});
